/* ---- KPI Tracker: multi-course single submission (patch, appended) ---- */
function lkpiRenderPendingCoursesHtml(){
    const list = (window.LKPI && window.LKPI.pendingCourses) || [];
    if(!list.length) return '<div class="text-muted" style="font-size:13px;">No courses added yet — add each course you teach, then Save Entry once.</div>';
    return '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px;">' + list.map((c,i) =>
        `<span class="badge" style="display:inline-flex;align-items:center;gap:6px;background:var(--color-surface-alt);border:1px solid var(--color-border-muted);padding:6px 10px;border-radius:20px;font-size:13px;">${escHtml(c.code)}${c.name ? " — " + escHtml(c.name) : ""}<button type="button" onclick="lkpiRemoveCourse(${i})" style="background:none;border:none;color:inherit;cursor:pointer;font-weight:bold;line-height:1;">✕</button></span>`
    ).join('') + '</div>';
}

window.lkpiCourseNameForCode = function(code){
    const e = window.LKPI;
    const norm = String(code || "").trim().toUpperCase();
    if(!norm) return "";
    const match = (e.courses || []).find(c => String(c.subject_code || "").toUpperCase() === norm);
    return match ? (match.subject_name || "") : "";
};

window.lkpiSyncCourseName = function(){
    const codeEl = document.getElementById("lkpi-course-code");
    const nameEl = document.getElementById("lkpi-course-name");
    if(!codeEl || !nameEl) return;
    nameEl.value = window.lkpiCourseNameForCode(codeEl.value);
};

window.lkpiAddCourse = function(){
    const e = window.LKPI;
    const codeEl = document.getElementById("lkpi-course-code");
    const nameEl = document.getElementById("lkpi-course-name");
    if(!codeEl) return;
    const code = (codeEl.value || "").trim().toUpperCase();
    if(!code) return void QMS.showToast("Select a course code first.", "error");
    e.pendingCourses = e.pendingCourses || [];
    if(e.pendingCourses.some(c => c.code === code)) return void QMS.showToast("That course is already added.", "error");
    const name = window.lkpiCourseNameForCode(code);
    e.pendingCourses.push({code, name});
    codeEl.value = "";
    if(nameEl) nameEl.value = "";
    const container = document.getElementById("lkpi-pending-courses");
    if(container) container.innerHTML = lkpiRenderPendingCoursesHtml();
    codeEl.focus();
};

window.lkpiRemoveCourse = function(i){
    const e = window.LKPI;
    e.pendingCourses = e.pendingCourses || [];
    e.pendingCourses.splice(i, 1);
    const container = document.getElementById("lkpi-pending-courses");
    if(container) container.innerHTML = lkpiRenderPendingCoursesHtml();
};

function lkpiBuildSectionData(existingRecord){
    const e = window.LKPI;
    const l = existingRecord || {};
    const sections = {};
    LKPI_SECTION_KEYS.forEach(t => {
        const a = (l || {})[t] || {}, n = {};
        LKPI_FIELDS[t].forEach(s => {
            if(lkpiFieldScoreable(s)){
                const i = `${t}.${s.key}`,
                    r = e.pendingRemoval && e.pendingRemoval.has(i),
                    o = !r && e.pendingEvidence && e.pendingEvidence[i],
                    ll = r ? null : a[s.key + "_evidence_url"],
                    d = o || ll;
                if(d){
                    n[s.key] = s.options[0];
                    n[s.key + "_evidence_url"] = d;
                } else {
                    const el = document.getElementById(`lkpi-${t}-${s.key}-select`);
                    if(el) n[s.key] = el.value;
                }
            } else {
                const el = document.getElementById(`lkpi-${t}-${s.key}`);
                if(el && el.value !== "") n[s.key] = s.type === "number" ? Number(el.value) : el.value;
            }
            if(s.extra){
                (Array.isArray(s.extra) ? s.extra : [s.extra]).forEach(ex => {
                    const el = document.getElementById(`lkpi-${t}-${ex.key}`);
                    if(el && el.value !== "") n[ex.key] = ex.type === "number" ? Number(el.value) : el.value;
                });
            }
        });
        sections[t] = n;
    });
    return sections;
}

/* Overrides the original single-course renderLKPIEntry — same layout, but the
   "Add Course Details" block becomes multi-course when creating a NEW entry
   (an "Add Course" button + a removable chip list), while editing an existing
   single record keeps the original single-course fields untouched. */
window.renderLKPIEntry = function(){
    const e = window.LKPI, t = QMS.state.user,
        a = document.getElementById("lkpi-tab-content"),
        n = "lecturer" === t.role,
        s = e.editingId ? e.records.find(x => x.id === e.editingId) : null,
        i = n ? `<option value="${t.id}" selected>${escHtml(t.name)}</option>` : '<option value="">— Select Lecturer —</option>' + e.staff.map(x => `<option value="${x.id}" ${s && s.lecturer_id === x.id ? "selected" : ""}>${escHtml(x.name)}</option>`).join(""),
        r = n ? e.records.filter(x => x.lecturer_id === t.id) : e.records;
    let o = "";
    if(s){
        const sc = lkpiComputeScore(s);
        let done = 0, total = 0;
        LKPI_SECTION_KEYS.forEach(k => {
            LKPI_FIELDS[k].filter(lkpiFieldScoreable).forEach(f => {
                total++;
                if((s[k] || {})[f.key + "_evidence_url"]) done++;
            });
        });
        o = `<div style="display:flex;align-items:center;gap:12px;margin-bottom:var(--sp-md);">${lkpiScoreBadge(sc.pct)}<span class="text-muted" style="font-size:13px;">Evidence attached: ${done}/${total}</span></div>`;
    }

    const lkpiSortedCourses = (e.courses || []).slice().sort((a, b) => String(a.subject_code || "").localeCompare(String(b.subject_code || "")));
    const lkpiCourseOptionsHtml = (selectedCode) => {
        const norm = String(selectedCode || "").toUpperCase();
        const hasMatch = lkpiSortedCourses.some(c => String(c.subject_code || "").toUpperCase() === norm);
        const fallback = (selectedCode && !hasMatch) ? `<option value="${escHtml(selectedCode)}" selected>${escHtml(selectedCode)} (not in catalog)</option>` : "";
        const opts = lkpiSortedCourses.map(c => `<option value="${escHtml(c.subject_code)}" ${String(c.subject_code || "").toUpperCase() === norm ? "selected" : ""}>${escHtml(c.subject_code)} — ${escHtml(c.subject_name || "")}</option>`).join("");
        return `<option value="">— Select Course Code —</option>${fallback}${opts}`;
    };
    const courseBlock = s
        ? `<div class="form-group">
                <label class="form-label">2. Course Details</label>
                <div style="display:flex;gap:12px;flex-wrap:wrap;">
                    <select class="form-input" style="flex:1;min-width:180px;" id="lkpi-course-code" onchange="lkpiSyncCourseName()">${lkpiCourseOptionsHtml(s.course_code)}</select>
                    <input class="form-input" style="flex:1;min-width:180px;background:rgba(255,255,255,0.04);" id="lkpi-course-name" placeholder="Auto-filled from course code" value="${escHtml(s.course_name || "")}" readonly />
                </div>
           </div>`
        : `<div class="form-group">
                <label class="form-label">2. Add Course(s) Taught</label>
                <div style="display:flex;gap:12px;flex-wrap:wrap;">
                    <select class="form-input" style="flex:1;min-width:180px;" id="lkpi-course-code" onchange="lkpiSyncCourseName()">${lkpiCourseOptionsHtml("")}</select>
                    <input class="form-input" style="flex:1;min-width:180px;background:rgba(255,255,255,0.04);" id="lkpi-course-name" placeholder="Auto-filled from course code" readonly />
                    <button type="button" class="btn btn-ghost" onclick="lkpiAddCourse()">➕ Add Course</button>
                </div>
                <div id="lkpi-pending-courses">${lkpiRenderPendingCoursesHtml()}</div>
                <div class="text-muted" style="font-size:12px;margin-top:6px;">Add every course you teach this semester, then Save Entry once to log KPI status for all of them together.</div>
           </div>`;

    a.innerHTML = `
                <div class="glass-card">
                    <div class="form-group">
                        <label class="form-label">1. Select Lecturer Profile (A-Z)</label>
                        <select class="form-input" id="lkpi-lecturer" ${n ? "disabled" : ""} onchange="lkpiOnLecturerChange()">${i}</select>
                    </div>
                    <div class="form-group">
                        <label class="form-label">Department / Faculty</label>
                        <select class="form-input" id="lkpi-dept">${LKPI_DEPTS.map(d => `<option value="${d}" ${s && s.school === d ? "selected" : ""}>${d}</option>`).join("")}</select>
                    </div>
                    ${courseBlock}
                    <div class="form-group">
                        <label class="form-label">Existing Record</label>
                        <select class="form-input" id="lkpi-existing-record" onchange="lkpiLoadExistingRecord(this.value)">
                            <option value="">— New Entry —</option>
                            ${r.map(x => `<option value="${x.id}" ${e.editingId === x.id ? "selected" : ""}>${escHtml(x.lecturer_name)} — ${escHtml(x.course_code)}</option>`).join("")}
                        </select>
                    </div>
                    ${o}
                    <hr style="border-color:var(--color-border-muted);margin:var(--sp-lg) 0;" />
                    <form id="lkpi-form" onsubmit="return false;">
                        ${LKPI_SECTION_KEYS.map((k, idx) => lkpiRenderSectionFields(k, LKPI_SECTION_LABELS[idx], s)).join("")}
                    </form>
                    <div style="display:flex;gap:12px;">
                        <button class="btn btn-primary" onclick="lkpiSubmitEntry()">💾 Save Entry${s ? "" : " (All Courses Above)"}</button>
                        <button class="btn btn-ghost" onclick="lkpiResetForm()">Reset</button>
                    </div>
                </div>
            `;
    if(n && !s){
        const staffRec = e.staff.find(x => x.id === t.id);
        const sch = (staffRec?.school || t.school || "").toUpperCase();
        const deptSel = document.getElementById("lkpi-dept");
        if(deptSel && [...deptSel.options].some(x => x.value === sch)) deptSel.value = sch;
    }
};

/* Overrides: clear the pending multi-course list whenever the lecturer changes,
   an existing record is opened for edit, or the form is reset. */
window.lkpiOnLecturerChange = function(){
    const e = window.LKPI;
    const lecSel = document.getElementById("lkpi-lecturer");
    const staffRec = e.staff.find(x => x.id === lecSel.value);
    if(staffRec && staffRec.school){
        const deptSel = document.getElementById("lkpi-dept");
        const sch = staffRec.school.toUpperCase();
        if(deptSel && [...deptSel.options].some(x => x.value === sch)) deptSel.value = sch;
    }
    e.pendingCourses = [];
};

window.lkpiLoadExistingRecord = function(id){
    const e = window.LKPI;
    e.editingId = id || null;
    e.pendingEvidence = {};
    e.pendingRemoval = new Set;
    e.pendingCourses = [];
    renderLKPIEntry();
};

window.lkpiResetForm = function(){
    const e = window.LKPI;
    e.editingId = null;
    e.pendingEvidence = {};
    e.pendingRemoval = new Set;
    e.pendingCourses = [];
    renderLKPIEntry();
};

/* Overrides the original single-course save with a multi-course bulk save.
   Editing an existing single record still saves just that one record. Creating
   a new entry saves every course added to the list (plus anything typed but
   not yet clicked "Add") in one action — one lecturer_kpi row per course,
   updating a course's existing row if that lecturer already has one. */
window.lkpiSubmitEntry = async function(){
    const e = window.LKPI, t = QMS.state.user,
        lecId = document.getElementById("lkpi-lecturer").value,
        staffRec = e.staff.find(x => x.id === lecId),
        lecName = staffRec?.name || (t.id === lecId ? t.name : ""),
        dept = document.getElementById("lkpi-dept").value;

    if(!lecId) return void QMS.showToast("Please select a lecturer.", "error");

    if(e.editingId){
        const codeEl = document.getElementById("lkpi-course-code"), nameEl = document.getElementById("lkpi-course-name");
        const code = codeEl.value.trim();
        if(!code) return void QMS.showToast("Please select a course code.", "error");
        const existing = e.records.find(x => x.id === e.editingId);
        const name = window.lkpiCourseNameForCode(code) || (existing?.course_name || nameEl.value.trim());
        const d = {
            lecturer_id: lecId, lecturer_name: lecName, school: dept,
            course_code: code, course_name: name || null,
            updated_by: t.id, updated_at: (new Date).toISOString(),
            ...lkpiBuildSectionData(existing)
        };
        try {
            const {error} = await supabaseClient.from("lecturer_kpi").update(d).eq("id", e.editingId);
            if(error) throw error;
            QMS.showToast("KPI entry saved.", "success");
            e.pendingEvidence = {}; e.pendingRemoval = new Set; e.pendingCourses = [];
            await lkpiLoadData();
            window.LKPI.activeTab = "dashboard";
            document.querySelectorAll("#main-content .tab-bar .tab-item").forEach(x => x.classList.toggle("active", "dashboard" === x.dataset.tab));
            renderLKPITabContent();
        } catch(err){ QMS.showToast("Error saving entry: " + err.message, "error"); }
        return;
    }

    const codeEl = document.getElementById("lkpi-course-code");
    const typedCode = (codeEl.value || "").trim().toUpperCase();
    let courses = (e.pendingCourses || []).slice();
    if(typedCode && !courses.some(c => c.code === typedCode)) courses.push({code: typedCode, name: window.lkpiCourseNameForCode(typedCode)});
    if(!courses.length) return void QMS.showToast("Add at least one course.", "error");

    const now = (new Date).toISOString();
    let successCount = 0;
    const errors = [];
    for(const c of courses){
        const existing = e.records.find(rec => rec.lecturer_id === lecId && rec.course_code === c.code);
        const d = {
            lecturer_id: lecId, lecturer_name: lecName, school: dept,
            course_code: c.code, course_name: c.name || null,
            updated_by: t.id, updated_at: now,
            ...lkpiBuildSectionData(existing || null)
        };
        try {
            let error;
            if(existing) ({error} = await supabaseClient.from("lecturer_kpi").update(d).eq("id", existing.id));
            else ({error} = await supabaseClient.from("lecturer_kpi").insert(d));
            if(error) throw error;
            successCount++;
        } catch(err){ errors.push(`${c.code}: ${err.message}`); }
    }
    if(successCount) QMS.showToast(`Saved KPI entries for ${successCount} course${successCount > 1 ? "s" : ""}.`, errors.length ? "error" : "success");
    if(errors.length) QMS.showToast("Some courses failed: " + errors.join("; "), "error");
    e.pendingEvidence = {}; e.pendingRemoval = new Set; e.pendingCourses = [];
    await lkpiLoadData();
    window.LKPI.activeTab = "dashboard";
    document.querySelectorAll("#main-content .tab-bar .tab-item").forEach(x => x.classList.toggle("active", "dashboard" === x.dataset.tab));
    renderLKPITabContent();
};

/* ---- Live Chat: open to everyone (students, lecturers, HOPs, deans) ---- */
/* Overrides mountStudentChat with a unified directory across students_directory
   and staff_directory (lecturer/hop/dean), so any role can request, approve,
   and message any other role. Request/approve/message/block plumbing (the
   peer_chat_requests / peer_chat_messages / peer_chat_blocks tables) is unchanged
   — those RLS policies are already generic on auth.uid(), not role-scoped. */
window.mountStudentChat = function(){
    falEnsureFonts();
    const e = document.getElementById("main-content"), t = QMS.state.user;
    const ROLE_LABELS = {student: "Student", lecturer: "Lecturer", hop: "HOP", dean: "Dean"};
    let a = [], n = [], s = [], i = [], r = "home", o = null, l = "";

    function d(name){ return (name || "?").trim().split(/\s+/).slice(0, 2).map(w => w[0]).join("").toUpperCase(); }
    function c(person){ return person && person.avatar_url ? `<img src="${escHtml(person.avatar_url)}" alt=""/>` : `<span>${d(person?.name)}</span>`; }
    function u(){ return new Set(i.filter(x => x.blocker_id === t.id).map(x => x.blocked_id)); }
    function p(){
        const blockedByMe = u();
        const blockedMe = new Set(i.filter(x => x.blocked_id === t.id).map(x => x.blocker_id));
        return a.filter(x => x.id !== t.id && !blockedByMe.has(x.id) && !blockedMe.has(x.id));
    }
    function m(id){
        const reqs = n.filter(x => x.requester_id === t.id && x.recipient_id === id || x.requester_id === id && x.recipient_id === t.id)
            .sort((x, y) => new Date(y.created_at) - new Date(x.created_at));
        const approved = reqs.find(x => "approved" === x.status);
        if(approved) return {state: "approved", req: approved};
        const first = reqs[0];
        return first && "pending" === first.status ? {state: first.requester_id === t.id ? "sent" : "incoming", req: first} : {state: "none", req: null};
    }
    function v(id){
        return s.filter(x => x.sender_id === t.id && x.recipient_id === id || x.sender_id === id && x.recipient_id === t.id)
            .sort((x, y) => new Date(x.created_at) - new Date(y.created_at));
    }
    async function f(){
        const [{data: students}, {data: staff}, {data: reqs}, {data: msgs}, {data: blocks}] = await Promise.all([
            supabaseClient.from("students_directory").select("id, name, programme, avatar_url"),
            supabaseClient.from("staff_directory").select("id, name, role, programme, school, avatar_url").in("role", ["lecturer", "hop", "dean"]),
            supabaseClient.from("peer_chat_requests").select("*").or(`requester_id.eq.${t.id},recipient_id.eq.${t.id}`),
            supabaseClient.from("peer_chat_messages").select("*").or(`sender_id.eq.${t.id},recipient_id.eq.${t.id}`),
            supabaseClient.from("peer_chat_blocks").select("*").or(`blocker_id.eq.${t.id},blocked_id.eq.${t.id}`)
        ]);
        const studentsTagged = (students || []).map(x => ({...x, roleTag: "Student"}));
        const staffTagged = (staff || []).map(x => ({...x, roleTag: ROLE_LABELS[x.role] || x.role}));
        a = studentsTagged.concat(staffTagged);
        n = reqs || []; s = msgs || []; i = blocks || [];
    }
    function b(){
        const conversations = (function(){
            const people = p(), peopleIds = new Set(people.map(x => x.id)), byId = new Map();
            n.filter(x => "approved" === x.status).forEach(req => {
                const otherId = req.requester_id === t.id ? req.recipient_id : req.requester_id;
                if(!peopleIds.has(otherId)) return;
                const person = people.find(x => x.id === otherId);
                if(person) byId.set(otherId, person);
            });
            const rows = Array.from(byId.values()).map(person => {
                const thread = v(person.id);
                return {student: person, last: thread[thread.length - 1], unread: s.filter(x => x.sender_id === person.id && x.recipient_id === t.id && !x.read_at).length};
            });
            rows.sort((x, y) => new Date(y.last?.created_at || 0) - new Date(x.last?.created_at || 0));
            return rows;
        })();
        const incomingRequests = n.filter(x => x.recipient_id === t.id && "pending" === x.status).sort((x, y) => new Date(y.created_at) - new Date(x.created_at));
        const blockedUsers = (function(){ const blockedByMe = u(); return a.filter(x => blockedByMe.has(x.id)); })();
        const findable = p().filter(x => !l || x.name.toLowerCase().includes(l.toLowerCase())).sort((x, y) => {
            const xOn = QMS.state.onlineStudents.has(x.id) ? 1 : 0, yOn = QMS.state.onlineStudents.has(y.id) ? 1 : 0;
            return xOn !== yOn ? yOn - xOn : (x.name || "").localeCompare(y.name || "");
        });
        e.innerHTML = `<div class="page-anim pchat-shell">
                    <div class="page-header">
                        <div class="pchat-eyebrow">COMMUNICATION · LIVE</div>
                        <div class="pchat-title">🟢 Live Chat</div>
                        <div class="pchat-desc">Request to chat with anyone — students, lecturers, HOPs, or deans — approve incoming requests, and message safely with block controls.</div>
                    </div>

                    ${0 === incomingRequests.length ? "" : `
                    <div class="pchat-panel mb-lg">
                        <div class="pchat-panel-heading"><span class="pchat-heading-label">📨 Chat Requests</span><span class="pchat-badge-count">${incomingRequests.length}</span></div>
                        <div class="pchat-panel-body">
                            ${incomingRequests.map(req => `<div class="pchat-request-row">
                                <div class="pchat-identity"><div class="pchat-avatar-badge">${d(req.requester_name)}</div><div class="pchat-name-block"><b>${escHtml(req.requester_name)}</b><small>wants to chat with you</small></div></div>
                                <div class="pchat-actions">
                                    <button class="pchat-btn" onclick="pchatApproveRequest('${req.id}')">✓ Approve</button>
                                    <button class="pchat-btn pchat-danger" onclick="pchatRejectRequest('${req.id}')">✕ Reject</button>
                                </div>
                            </div>`).join("")}
                        </div>
                    </div>`}

                    <div class="pchat-panel mb-lg">
                        <div class="pchat-panel-heading"><span class="pchat-heading-label">💬 Conversations</span>${conversations.reduce((sum, x) => sum + x.unread, 0) > 0 ? `<span class="pchat-badge-count">${conversations.reduce((sum, x) => sum + x.unread, 0)}</span>` : ""}</div>
                        <div class="pchat-panel-body">
                            ${0 === conversations.length ? '<div class="pchat-empty">No conversations yet — request to chat with someone below to get started.</div>' : `<div class="pchat-roster">${conversations.map(conv => `<div class="pchat-row" style="cursor:pointer;" onclick="pchatOpenThread('${conv.student.id}','${escHtml(conv.student.name)}')">
                                <div class="pchat-identity"><div class="pchat-avatar-badge">${c(conv.student)}</div><div class="pchat-name-block"><b>${escHtml(conv.student.name)}</b> <span class="badge badge-cyan" style="font-size:10px;">${conv.student.roleTag}</span><small>${conv.last ? escHtml((conv.last.sender_id === t.id ? "You: " : "") + conv.last.content.slice(0, 32) + (conv.last.content.length > 32 ? "…" : "")) : "Say hello!"}</small></div></div>
                                <div class="pchat-actions"><span class="pchat-status-dot ${QMS.state.onlineStudents.has(conv.student.id) ? "online" : "offline"}"></span>${conv.unread > 0 ? `<span class="pchat-badge-count">${conv.unread}</span>` : ""}</div>
                            </div>`).join("")}</div>`}
                        </div>
                    </div>

                    <div class="pchat-panel mb-lg">
                        <div class="pchat-panel-heading"><span class="pchat-heading-label">🧑‍🤝‍🧑 Find People</span></div>
                        <div class="pchat-panel-body">
                            <input type="text" id="pchat-search-input" class="pchat-search" placeholder="Search by name…" value="${escHtml(l)}" oninput="pchatSetSearch(this.value)"/>
                            ${0 === findable.length ? '<div class="pchat-empty">No one found.</div>' : `<div class="pchat-roster">${findable.map(person => {
                                const online = QMS.state.onlineStudents.has(person.id), st = m(person.id);
                                let actions = "";
                                actions = "approved" === st.state ? `<button class="pchat-btn" onclick="pchatOpenThread('${person.id}','${escHtml(person.name)}')">💬 Open Chat</button>`
                                    : "sent" === st.state ? '<button class="pchat-btn" disabled>⏳ Request Sent</button>'
                                    : "incoming" === st.state ? `<button class="pchat-btn" onclick="pchatApproveRequest('${st.req.id}')">✓ Approve</button><button class="pchat-btn pchat-danger" onclick="pchatRejectRequest('${st.req.id}')">✕</button>`
                                    : `<button class="pchat-btn" onclick="pchatSendRequest('${person.id}','${escHtml(person.name)}')">＋ Request to Chat</button>`;
                                return `<div class="pchat-row">
                                    <div class="pchat-identity"><div class="pchat-avatar-badge">${c(person)}</div><div class="pchat-name-block"><b>${escHtml(person.name)}</b> <span class="badge badge-cyan" style="font-size:10px;">${person.roleTag}</span><small><span class="pchat-status-dot ${online ? "online" : "offline"}"></span>${online ? "Online" : "Offline"} · ${escHtml(person.programme || person.school || "")}</small></div></div>
                                    <div class="pchat-actions">${actions}</div>
                                </div>`;
                            }).join("")}</div>`}
                        </div>
                    </div>

                    ${0 === blockedUsers.length ? "" : `
                    <div class="pchat-panel">
                        <div class="pchat-panel-heading"><span class="pchat-heading-label">🚫 Blocked Users</span></div>
                        <div class="pchat-panel-body">
                            <div class="pchat-roster">${blockedUsers.map(person => `<div class="pchat-row">
                                <div class="pchat-identity"><div class="pchat-avatar-badge">${c(person)}</div><div class="pchat-name-block"><b>${escHtml(person.name)}</b> <span class="badge badge-cyan" style="font-size:10px;">${person.roleTag}</span><small>Blocked</small></div></div>
                                <div class="pchat-actions"><button class="pchat-btn pchat-ghost" onclick="pchatUnblockUser('${person.id}')">Unblock</button></div>
                            </div>`).join("")}</div>
                        </div>
                    </div>`}
                </div>`;
    }
    function g(){ const box = document.getElementById("pchat-thread-body"); if(box) box.scrollTop = box.scrollHeight; }
    function appendBubble(msg){
        const otherId = msg.sender_id === t.id ? msg.recipient_id : msg.sender_id;
        if(!("thread" === r && o && o.id === otherId)) return false;
        const body = document.getElementById("pchat-thread-body");
        if(!body) return false;
        const empty = body.querySelector(".pchat-empty");
        if(empty) empty.remove();
        const row = document.createElement("div");
        row.className = "pchat-bubble-row " + (msg.sender_id === t.id ? "mine" : "");
        row.innerHTML = `<div class="pchat-bubble">${escHtml(msg.content)}<span class="pchat-bubble-time">${fmtDateTime(msg.created_at)}</span></div>`;
        body.appendChild(row);
        g();
        return true;
    }
    async function h(person){
        m(person.id);
        const blocked = u().has(person.id), thread = v(person.id), online = QMS.state.onlineStudents.has(person.id);
        const full = a.find(x => x.id === person.id);
        e.innerHTML = `<div class="page-anim pchat-shell">
                    <button class="pchat-btn pchat-ghost" onclick="pchatBackToHome()">← Back to Live Chat</button>
                    <div class="pchat-panel" style="margin-top:12px;">
                        <div class="pchat-thread">
                            <div class="pchat-thread-header">
                                <div class="pchat-identity"><div class="pchat-avatar-badge">${c(full)}</div><div class="pchat-name-block"><b>${escHtml(person.name)}</b> ${full ? `<span class="badge badge-cyan" style="font-size:10px;">${full.roleTag}</span>` : ""}<small><span class="pchat-status-dot ${online ? "online" : "offline"}"></span>${online ? "Online" : "Offline"}</small></div></div>
                                <button class="pchat-btn pchat-danger" onclick="pchatConfirmBlock('${person.id}','${escHtml(person.name)}')">🚫 Block</button>
                            </div>
                            ${blocked ? `<div class="pchat-blocked-banner">You have blocked ${escHtml(person.name)}. Unblock them from the Live Chat home screen to resume messaging.</div>` : ""}
                            <div class="pchat-thread-body" id="pchat-thread-body">
                                ${0 === thread.length ? '<div class="pchat-empty">No messages yet. Say hello 👋</div>' : thread.map(msg => `<div class="pchat-bubble-row ${msg.sender_id === t.id ? "mine" : ""}"><div class="pchat-bubble">${escHtml(msg.content)}<span class="pchat-bubble-time">${fmtDateTime(msg.created_at)}</span></div></div>`).join("")}
                            </div>
                            <div class="pchat-composer">
                                <input id="pchat-msg-input" type="text" placeholder="${blocked ? "Unblock to send messages" : "Type a message…"}" ${blocked ? "disabled" : ""} onkeydown="if(event.key==='Enter'){event.preventDefault();pchatSendMessage('${person.id}','${escHtml(person.name)}');}"/>
                                <button ${blocked ? "disabled" : ""} onclick="pchatSendMessage('${person.id}','${escHtml(person.name)}')">➤</button>
                            </div>
                        </div>
                    </div>
                </div>`;
        g();
        const toMark = thread.filter(msg => msg.sender_id === person.id && msg.recipient_id === t.id && !msg.read_at).map(msg => msg.id);
        if(toMark.length > 0){
            await supabaseClient.from("peer_chat_messages").update({read_at: now()}).in("id", toMark);
            toMark.forEach(id => { const msg = s.find(x => x.id === id); if(msg) msg.read_at = now(); });
        }
    }
    function x(){
        if("thread" === r && o) return void h(o);
        const active = document.activeElement, isSearch = active && "pchat-search-input" === active.id, caret = isSearch ? active.selectionStart : null;
        b();
        if(isSearch){
            const inp = document.getElementById("pchat-search-input");
            if(inp){ inp.focus(); const pos = Math.min(caret ?? inp.value.length, inp.value.length); inp.setSelectionRange(pos, pos); }
        }
    }
    let debounce = null;
    window.pchatSetSearch = function(val){ l = val; clearTimeout(debounce); debounce = setTimeout(() => { x(); }, 250); };
    window.pchatSendRequest = async function(id, name){
        const {error} = await supabaseClient.from("peer_chat_requests").insert({requester_id: t.id, requester_name: t.name, recipient_id: id, recipient_name: name, status: "pending"});
        error ? QMS.showToast("Error: " + error.message, "error") : (QMS.showToast("Chat request sent to " + name, "success"), await f(), x());
    };
    window.pchatApproveRequest = async function(id){
        const {error} = await supabaseClient.from("peer_chat_requests").update({status: "approved", responded_at: now()}).eq("id", id);
        error ? QMS.showToast("Error: " + error.message, "error") : (QMS.showToast("Chat request approved", "success"), await f(), x());
    };
    window.pchatRejectRequest = async function(id){
        const {error} = await supabaseClient.from("peer_chat_requests").update({status: "rejected", responded_at: now()}).eq("id", id);
        error ? QMS.showToast("Error: " + error.message, "error") : (QMS.showToast("Chat request rejected", "info"), await f(), x());
    };
    window.pchatOpenThread = async function(id, name){ r = "thread"; o = {id, name}; await h(o); };
    window.pchatBackToHome = async function(){ r = "home"; o = null; await f(); b(); };
    window.pchatSendMessage = async function(id, name){
        const inp = document.getElementById("pchat-msg-input"), text = inp?.value?.trim();
        if(!text) return;
        if("approved" !== m(id).state) return void QMS.showToast("You can only message after your chat request is approved", "error");
        if(u().has(id)) return void QMS.showToast("Unblock this user to send messages", "error");
        const {data, error} = await supabaseClient.from("peer_chat_messages").insert({sender_id: t.id, sender_name: t.name, recipient_id: id, recipient_name: name, content: text}).select().single();
        if(error){ QMS.showToast("Error: " + error.message, "error"); return; }
        inp.value = "";
        inp.focus();
        const sentMsg = data || {id: "tmp-" + Date.now() + "-" + Math.random(), sender_id: t.id, recipient_id: id, content: text, created_at: new Date().toISOString()};
        if(!s.some(x => x.id === sentMsg.id)) s.push(sentMsg);
        appendBubble(sentMsg);
        f();
    };
    window.pchatConfirmBlock = function(id, name){
        QMS.confirm("Block " + name + "?", "They will no longer be able to send you chat requests or messages, and this conversation will be hidden from your list. You can unblock them anytime.", async () => {
            const {error} = await supabaseClient.from("peer_chat_blocks").insert({blocker_id: t.id, blocked_id: id});
            error ? QMS.showToast("Error: " + error.message, "error") : (QMS.showToast(name + " has been blocked", "success"), r = "home", o = null, await f(), b());
        });
    };
    window.pchatUnblockUser = async function(id){
        const {error} = await supabaseClient.from("peer_chat_blocks").delete().eq("blocker_id", t.id).eq("blocked_id", id);
        error ? QMS.showToast("Error: " + error.message, "error") : (QMS.showToast("User unblocked", "success"), await f(), b());
    };
    window.__pchatRefresh = async function(){ await f(); x(); };
    window.__pchatApplyMessage = function(eventType, msg){
        if("INSERT" !== eventType || !msg) return void window.__pchatRefresh();
        const isNew = !s.some(x => x.id === msg.id);
        if(isNew) s.push(msg);
        const otherId = msg.sender_id === t.id ? msg.recipient_id : msg.sender_id;
        if("thread" === r && o && o.id === otherId){
            if(isNew) appendBubble(msg);
            if(msg.recipient_id === t.id && !msg.read_at){
                supabaseClient.from("peer_chat_messages").update({read_at: now()}).eq("id", msg.id).then(() => { msg.read_at = now(); });
            }
        } else if(isNew){
            x();
        }
    };
    window.__pchatRefreshPresence = function(){ "student-chat" === QMS.state.currentSection && x(); };
    return f().then(() => x());
};

// ===================== EVENTS FEATURE =====================
const EVENT_TYPE_LABELS = { workshop: "Workshop", talk: "Talk / Guest Lecture", seminar: "Seminar", competition: "Competition" };
const EVENT_TYPE_BADGE = { workshop: "cyan", talk: "violet", seminar: "warning", competition: "green" };
const QE_STAFF_ROLES = ["lecturer", "hop", "dean", "admin"];

function qeDayName(dateStr) {
    return new Date(dateStr + "T00:00:00").toLocaleDateString("en-MY", { weekday: "long" });
}

function qeIcsFor(ev) {
    const d = ev.event_date.replace(/-/g, "");
    const uid = ev.id + "@unimy-qms-rise";
    const desc = (ev.description || "").replace(/\n/g, "\\n");
    return "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//UNIMY QMS RISE//Events//EN\r\nBEGIN:VEVENT\r\nUID:" + uid + "\r\nDTSTAMP:" + now().replace(/[-:]/g, "").split(".")[0] + "Z\r\nDTSTART;VALUE=DATE:" + d + "\r\nSUMMARY:" + ev.title.replace(/\n/g, " ") + "\r\nDESCRIPTION:" + desc + "\r\nLOCATION:" + (ev.location || "") + "\r\nEND:VEVENT\r\nEND:VCALENDAR";
}

window.qeDownloadIcs = function (eventId) {
    const ev = (QMS.state.eventsCache || []).find(e => e.id === eventId);
    if (!ev) return;
    const blob = new Blob([qeIcsFor(ev)], { type: "text/calendar" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = ev.title.replace(/[^a-z0-9]+/gi, "-").slice(0, 40) + ".ics";
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
};

window.qeSetTab = function (tab) {
    QMS.state.eventsTab = tab;
    mountEvents();
};

window.qeOpenAddEvent = function (id) {
    const ev = id ? (QMS.state.eventsCache || []).find(e => e.id === id) : null;
    QMS.showModal(`<div class="modal-header"><span class="modal-title">${ev ? "Edit Event" : "Add New Event"}</span></div>
        <div class="form-group"><label class="form-label">Event Name</label><input type="text" class="form-input" id="qe-title" value="${escHtml(ev ? ev.title : "")}" placeholder="e.g. AI in Healthcare Workshop"/></div>
        <div class="grid-2">
            <div class="form-group"><label class="form-label">Type of Event</label><select class="form-input" id="qe-type">${Object.entries(EVENT_TYPE_LABELS).map(([k, v]) => `<option value="${k}" ${ev && ev.event_type === k ? "selected" : ""}>${v}</option>`).join("")}</select></div>
            <div class="form-group"><label class="form-label">Rise Points</label><input type="number" min="0" class="form-input" id="qe-points" value="${ev ? ev.rise_points : 10}"/></div>
        </div>
        <div class="grid-2">
            <div class="form-group"><label class="form-label">Date</label><input type="date" class="form-input" id="qe-date" value="${ev ? ev.event_date : ""}"/></div>
            <div class="form-group"><label class="form-label">Location</label><input type="text" class="form-input" id="qe-location" value="${escHtml(ev ? ev.location || "" : "")}" placeholder="e.g. Auditorium A"/></div>
        </div>
        <div class="form-group"><label class="form-label">Description</label><textarea class="form-input" id="qe-desc" placeholder="Details for students...">${escHtml(ev ? ev.description || "" : "")}</textarea></div>
        <div class="modal-footer">
            <button class="btn btn-ghost" onclick="QMS.closeModal()">Cancel</button>
            <button class="btn btn-accent" onclick="qeSaveEvent(${ev ? `'${ev.id}'` : "null"})">${ev ? "Save Changes" : "Create Event"}</button>
        </div>`, "wide");
};

window.qeSaveEvent = async function (id) {
    const title = document.getElementById("qe-title").value.trim();
    const event_type = document.getElementById("qe-type").value;
    const rise_points = parseInt(document.getElementById("qe-points").value, 10) || 0;
    const event_date = document.getElementById("qe-date").value;
    const location = document.getElementById("qe-location").value.trim();
    const description = document.getElementById("qe-desc").value.trim();
    if (!title || !event_date) return QMS.showToast("Event name and date are required", "error");
    const u = QMS.state.user;
    const payload = { title, event_type, rise_points, event_date, location, description };
    let error;
    if (id) {
        ({ error } = await supabaseClient.from("events").update(payload).eq("id", id));
    } else {
        ({ error } = await supabaseClient.from("events").insert({ ...payload, created_by: u.id, created_by_name: u.name }));
    }
    if (error) return QMS.showToast("Error: " + error.message, "error");
    QMS.showToast(id ? "Event updated" : "Event created", "success");
    QMS.closeModal();
    mountEvents();
};

window.qeDeleteEvent = function (id) {
    QMS.confirm("Delete Event", "This will remove the event and all student bookings for it. Continue?", async () => {
        const { error } = await supabaseClient.from("events").delete().eq("id", id);
        if (error) return QMS.showToast("Error: " + error.message, "error");
        QMS.showToast("Event deleted", "success");
        mountEvents();
    });
};

window.qeBookEvent = async function (id) {
    const u = QMS.state.user;
    const { error } = await supabaseClient.from("event_bookings").insert({ event_id: id, student_id: u.id, student_name: u.name });
    if (error) return QMS.showToast("Error: " + error.message, "error");
    QMS.showToast("Booked! Added to your calendar.", "success");
    mountEvents();
};

window.qeCancelBooking = function (bookingId) {
    QMS.confirm("Cancel Booking", "Remove this event from your bookings?", async () => {
        const { error } = await supabaseClient.from("event_bookings").delete().eq("id", bookingId);
        if (error) return QMS.showToast("Error: " + error.message, "error");
        QMS.showToast("Booking cancelled", "success");
        mountEvents();
    });
};

window.qeViewAttendees = async function (eventId) {
    const ev = (QMS.state.eventsCache || []).find(e => e.id === eventId);
    const { data: bookings, error } = await supabaseClient.from("event_bookings").select("*").eq("event_id", eventId).order("booked_at", { ascending: true });
    if (error) return QMS.showToast("Error loading attendees: " + error.message, "error");
    const rows = (bookings || []).map(b => `<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid var(--glass-border);">
            <div><div style="font-weight:600;">${escHtml(b.student_name || b.student_id)}</div><div class="text-muted text-sm">Booked ${fmtDate(b.booked_at)}</div></div>
            ${b.attended
            ? `<span class="badge badge-green">Attended${b.points_awarded ? " · +" + ev.rise_points + " pts" : ""}</span>`
            : `<button class="btn btn-sm btn-accent" onclick="qeMarkAttended('${b.id}','${b.student_id}','${eventId}')">Mark Attended</button>`}
        </div>`).join("");
    QMS.showModal(`<div class="modal-header"><span class="modal-title">Attendees — ${escHtml(ev ? ev.title : "")}</span></div>
        <div class="text-muted text-sm mb-lg">${(bookings || []).length} student${(bookings || []).length === 1 ? "" : "s"} booked · Rise Points: ${ev ? ev.rise_points : 0}</div>
        <div>${rows || '<div class="empty-state" style="padding:20px;"><div class="empty-icon">🗒️</div><div class="empty-title">No bookings yet</div></div>'}</div>
        <div class="modal-footer"><button class="btn btn-ghost" onclick="QMS.closeModal()">Close</button></div>`, "wide");
};

window.qeMarkAttended = async function (bookingId, studentId, eventId) {
    const ev = (QMS.state.eventsCache || []).find(e => e.id === eventId);
    if (!ev) return QMS.showToast("Event not found", "error");
    const { error: upErr } = await supabaseClient.from("event_bookings").update({ attended: true, attended_at: now() }).eq("id", bookingId);
    if (upErr) return QMS.showToast("Error: " + upErr.message, "error");
    let pointsOk = true;
    if (ev.rise_points > 0) {
        pointsOk = await addRisePoints(studentId, ev.event_type, ev.rise_points, ev.title);
    }
    if (pointsOk) await supabaseClient.from("event_bookings").update({ points_awarded: true }).eq("id", bookingId);
    QMS.showToast("Attendance marked" + (pointsOk && ev.rise_points > 0 ? " · points awarded" : ""), "success");
    window.qeViewAttendees(eventId);
};

function qeRenderEventCard(ev, ctx) {
    const badge = EVENT_TYPE_BADGE[ev.event_type] || "neutral";
    const isPast = ev.event_date < new Date().toISOString().slice(0, 10);
    const myBooking = ctx.myBookings ? ctx.myBookings.find(b => b.event_id === ev.id) : null;
    let actionHtml = "";
    if (ctx.role === "student") {
        if (myBooking) {
            actionHtml = `<div class="btn-row mt-sm">
                <span class="badge ${myBooking.attended ? "badge-green" : "badge-cyan"}">${myBooking.attended ? "Attended ✓" : "Booked ✓"}</span>
                <button class="btn btn-sm btn-outline" onclick="qeDownloadIcs('${ev.id}')">📅 Add to Calendar</button>
                ${!myBooking.attended ? `<button class="btn btn-sm btn-ghost" onclick="qeCancelBooking('${myBooking.id}')">Cancel</button>` : ""}
            </div>`;
        } else if (!isPast) {
            actionHtml = `<div class="btn-row mt-sm"><button class="btn btn-sm btn-accent" onclick="qeBookEvent('${ev.id}')">Book This Event</button></div>`;
        }
    } else if (ctx.isManager) {
        actionHtml = `<div class="btn-row mt-sm">
            <button class="btn btn-sm btn-outline" onclick="qeViewAttendees('${ev.id}')">👥 Attendees</button>
            <button class="btn btn-sm btn-outline" onclick="qeOpenAddEvent('${ev.id}')">Edit</button>
            <button class="btn btn-sm btn-ghost" onclick="qeDeleteEvent('${ev.id}')">Delete</button>
        </div>`;
    }
    return `<div class="glass-card mb-lg" style="${isPast ? "opacity:0.6;" : ""}">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;">
            <div>
                <span class="badge badge-${badge}" style="margin-right:6px;">${EVENT_TYPE_LABELS[ev.event_type] || ev.event_type}</span>
                <span style="font-weight:700;font-size:16px;">${escHtml(ev.title)}</span>
            </div>
            <span class="badge badge-warning">⭐ ${ev.rise_points} pts</span>
        </div>
        <div class="text-muted text-sm" style="margin-top:4px;">📅 ${fmtDate(ev.event_date)} (${qeDayName(ev.event_date)})${ev.location ? " · 📍 " + escHtml(ev.location) : ""}</div>
        ${ev.description ? `<div class="text-sm" style="margin-top:6px;">${escHtml(ev.description)}</div>` : ""}
        ${ctx.isManager ? `<div class="text-muted text-sm" style="margin-top:4px;">Created by ${escHtml(ev.created_by_name || ev.created_by)}</div>` : ""}
        ${actionHtml}
    </div>`;
}

async function mountEvents() {
    const container = document.getElementById("main-content");
    const u = QMS.state.user;
    const isManager = QE_STAFF_ROLES.includes(u.role);
    const isStudent = u.role === "student";
    const today = new Date().toISOString().slice(0, 10);

    const { data: events, error } = await supabaseClient.from("events").select("*").order("event_date", { ascending: true });
    if (error) {
        container.innerHTML = `<div class="empty-state"><div class="empty-icon">⚠️</div><div class="empty-title">Could not load events</div><p class="text-muted">${escHtml(error.message)}</p></div>`;
        return;
    }
    QMS.state.eventsCache = events || [];

    let myBookings = [];
    if (isStudent) {
        const { data: bk } = await supabaseClient.from("event_bookings").select("*").eq("student_id", u.id);
        myBookings = bk || [];
    }

    const tab = QMS.state.eventsTab || "upcoming";
    const upcoming = (events || []).filter(e => e.event_date >= today);
    const past = (events || []).filter(e => e.event_date < today);
    const bookedEvents = myBookings.map(b => ({ ...(events || []).find(e => e.id === b.event_id), booking: b })).filter(e => e.id);

    const ctx = { role: u.role, isManager, myBookings };

    let listHtml;
    if (isStudent && tab === "mybookings") {
        listHtml = bookedEvents.length
            ? bookedEvents.map(e => qeRenderEventCard(e, ctx)).join("")
            : '<div class="empty-state"><div class="empty-icon">🗓️</div><div class="empty-title">No bookings yet</div><p class="text-muted">Book an upcoming event to see it here.</p></div>';
    } else if (tab === "past") {
        listHtml = past.length
            ? past.slice().reverse().map(e => qeRenderEventCard(e, ctx)).join("")
            : '<div class="empty-state"><div class="empty-icon">📭</div><div class="empty-title">No past events</div></div>';
    } else {
        listHtml = upcoming.length
            ? upcoming.map(e => qeRenderEventCard(e, ctx)).join("")
            : '<div class="empty-state"><div class="empty-icon">📭</div><div class="empty-title">No upcoming events</div></div>';
    }

    const tabsHtml = `<div class="btn-row mb-lg">
        <button class="btn btn-sm ${tab === "upcoming" || !tab ? "btn-accent" : "btn-outline"}" onclick="qeSetTab('upcoming')">Upcoming</button>
        ${isStudent ? `<button class="btn btn-sm ${tab === "mybookings" ? "btn-accent" : "btn-outline"}" onclick="qeSetTab('mybookings')">My Bookings (${bookedEvents.length})</button>` : ""}
        <button class="btn btn-sm ${tab === "past" ? "btn-accent" : "btn-outline"}" onclick="qeSetTab('past')">Past</button>
    </div>`;

    container.innerHTML = `<div class="page-anim">
        <div class="page-header">
            <div class="page-eyebrow">CAMPUS LIFE</div>
            <div class="page-title">🎫 Events</div>
            <div class="page-desc">${isManager ? "Create and manage campus events, and award Rise Points to attendees." : "Browse upcoming events and book your spot — it's added to your bookings automatically."}</div>
        </div>
        ${isManager ? `<div class="btn-row mb-lg"><button class="btn btn-accent" onclick="qeOpenAddEvent()">+ Add Event</button></div>` : ""}
        ${tabsHtml}
        <div>${listHtml}</div>
    </div>`;
}
