// CLEANUP: Remove SOCSI and unwanted nav items
// ════════════════════════════════════════════════════════════
setTimeout(() => {
  const navbar = document.getElementById('navbar');
  if (navbar) {
    // Remove SOCSI badges
    const SOCSIBadges = navbar.querySelectorAll('.so-csi-badge, .hero-eyebrow, .badge-text');
    SOCSIBadges.forEach(badge => {
      if (badge.textContent.includes('SOCSI') || badge.textContent.includes('School of Computing')) {
        badge.remove();
      }
    });
    
    // Remove Dashboard, Analytics, Documents nav items
    const navItems = navbar.querySelectorAll('.nav-item');
    navItems.forEach(item => {
      const text = item.textContent.toLowerCase();
      if (text.includes('dashboard') || text.includes('analytics') || text.includes('documents')) {
        item.remove();
      }
    });
    
    console.log('✅ Navbar cleaned - removed SOCSI and unwanted items');
  }
}, 1000);
